        public ShareaSaleService(HttpClient client, ILogger log)                
        {
            _log = log;
            try
            {
                IConfigurationBuilder builder = new ConfigurationBuilder()
                .AddJsonFile("appsettings.json");
                IConfigurationRoot configuration = builder.Build();
                ShareaSaleAPI = configuration.GetSection("ShareaSale");
                connection = configuration.GetSection("ConnectionStrings");
                MongoDb = configuration.GetSection("Mondodb");
                if (ShareaSaleAPI != null)
                {
                    _baseUrl = ShareaSaleAPI.GetSection("baseUrl").Value;
                    ShareaSaleAuthenicator.apiToken = ShareaSaleAPI.GetSection("token").Value;
                    ShareaSaleAuthenicator.apiSecret = ShareaSaleAPI.GetSection("secret").Value;
                    _apiVersion = ShareaSaleAPI.GetSection("version").Value;
                    _affiliateid = ShareaSaleAPI.GetSection("affiliateId").Value;
                    //conn = connection.GetSection("connection").Value;
                    //mongoConn = MongoDb.GetSection("connection").Value;
                }
                if (connection != null)
                    conn = connection.GetSection("connection").Value;
                if (mongoConn != null)
                    mongoConn = MongoDb.GetSection("connection").Value;
                //manager = new Manager(connection.GetSection("connection").Value, MongoDb.GetSection("connection").Value, _log);
            }
            catch (Exception ex)
            {
                _baseUrl = Environment.GetEnvironmentVariable("ShareaSaleBaseUrl");
                ShareaSaleAuthenicator.apiToken = Environment.GetEnvironmentVariable("ShareaSaleToken");
                ShareaSaleAuthenicator.apiSecret = Environment.GetEnvironmentVariable("ShareaSaleSecret");
                _apiVersion = Environment.GetEnvironmentVariable("ShareaSaleVersion");
                _affiliateid = Environment.GetEnvironmentVariable("ShareaSaleAffiliateId");
                conn = Environment.GetEnvironmentVariable("ConnectionString");
                mongoConn = Environment.GetEnvironmentVariable("MondodbConnection");
                //manager = new Manager(Environment.GetEnvironmentVariable("ConnectionString"), Environment.GetEnvironmentVariable("MondodbConnection"), _log);
            }

            //_connect = new MongodbConnect(MongoDb.GetSection("connection").Value, "Advertising");
        

            _client = client;
            timer = new Stopwatch();
            //_connection = new SqlConnection(conn);
            //_connection.Open();
            manager = new Manager(conn, mongoConn, _log);
        }
