        //https://api.shareasale.com/x.cfm?action=getProducts&affiliateId=867507&token=6ZdqHrOcduLfQC10&version=2.3&keyword=baseball
        public dynamic GetProducts(string keyword, ref dynamic error)
        {
            timer.Start();
            HttpRequestMessage request;
            RssModel results;
            _actionVerb = "getProducts";
            Dictionary<string, string> headers = new Dictionary<string, string>();
            ShareaSaleAuthenicator.ut = DateTime.Now.ToUniversalTime().ToString("r");
            x_ShareASale_Authentication = ShareaSaleAuthenicator.GenerateSignature(_actionVerb);
            string url = _baseUrl + "action=" + _actionVerb + "&affiliateId=" + _affiliateid + "&token=" + ShareaSaleAuthenicator.apiToken + "&version=" + _apiVersion + "&keyword=" + keyword;
            headers.Add("x-ShareASale-Authentication", x_ShareASale_Authentication);
            headers.Add("x-ShareASale-Date", ShareaSaleAuthenicator.ut);
            request = AuthenicationHelper.GetAuthenicatedRequest(HttpMethod.Get,url,headers, "application/json", "");
            //    ShareaSaleAuthenicator.ut = DateTime.Now.ToUniversalTime().ToString("r");
            //    x_ShareASale_Authentication = ShareaSaleAuthenicator.GenerateSignature(_actionVerb);
            //    string url = "action=" + _actionVerb + "&affiliateId=" + _affiliateid + "&token=" + ShareaSaleAuthenicator.apiToken + "&version=" + _apiVersion + "&keyword=" + keyWord;
            //    HttpRequestMessage request = new HttpRequestMessage(method, _baseUrl + url);
            //    request.Headers.Add("x-ShareASale-Authentication", x_ShareASale_Authentication);
            //    request.Headers.Add("x-ShareASale-Date", ShareaSaleAuthenicator.ut);
            //    request.Content = new StringContent(jsonString, Encoding.UTF8, "application/json");
            string result = APIProxy<dynamic>.SendString(request, ref error, _client);
            if (Errors.HasErrors(error))
            {
                return error;
            }
            results = StoreLoad(result);
            //results = StoreLoad();
            return results;
            //timer.Stop();
            //TimeSpan ts = timer.Elapsed;
            ////Console.WriteLine(nameof(ShareaSaleService) + " Processing Time - " + ts.Hours + ":" + ts.Minutes + ":" + ts.Seconds + ":" + ts.Milliseconds + ":");
        }

