            Stream sm = new MemoryStream(Encoding.UTF8.GetBytes(results));
            StreamReader sr = new StreamReader(sm);
            string line = string.Empty;
            int lineNumber = 0;
            bool isValid = false;
            while ((line = sr.ReadLine()) != null)
            {
                isValid = true;
                var fields = line.Split('|');
                if(lineNumber > 0 && fields.Length > 0)
                {
                    var items = new RssModelItems();
                    for(int I = 0; I <= fields.Length; I++)
                    {
                        switch (I)
                        {
                            case 1:
                                items.title = fields[I].Trim();
                                break;
                            case 4:
                                items.link = fields[I].Trim();
                                break;
                            case 6:
                                items.image = fields[I].Trim();
                                if (!ImageHelper.IsImageUrl(items.image,true, _client))
                                {
                                    isValid = false;
                                    break;
                                }
                                break;
                            case 7:
                                items.price = fields[I].Trim();
                                break;
                            case 11:
                                items.content = fields[I].Trim();
                                break;
                            case 17:
                                items.pubDate = fields[I].Trim();
                                break;
                            case 23:
                                items.source = fields[I].Trim();
                                break;
                        }
                    }
                    if(isValid)
                        rss.items.Add(items);
                }
                lineNumber += 1;
                if (lineNumber == 100)
                    break;
            }
            rss.items.ToList().Shuffle<RssModelItems>();
            //rss.items = rss.items.Take(80).ToList();
